using System;
using System.Threading;
using System.Threading.Tasks;

public class Program
{
    private static int _unsafeCounter = 0;
    private static int _safeCounter = 0;

    public static async Task Main()
    {
        int iterations = 100_000;
        var tasks = new Task[4];

        for (int t = 0; t < 4; t++)
        {
            tasks[t] = Task.Run(() =>
            {
                for (int i = 0; i < iterations; i++)
                {
                    _unsafeCounter++;
                    Interlocked.Increment(ref _safeCounter);
                }
            });
        }

        await Task.WhenAll(tasks);

        Console.WriteLine($"Ekspektasi Total: {4 * iterations}");
        Console.WriteLine($"Unsafe Counter  : {_unsafeCounter} (Seringkali hilang data akibat race condition)");
        Console.WriteLine($"Safe Counter    : {_safeCounter} (Harus tepat {4 * iterations})");
    }
}

